import{_ as t,o,c as a,a2 as s}from"./chunks/framework.vLhlLNVn.js";const n="/assets/befehl-zum-geraet.CJpsfUc0.svg",p=JSON.parse('{"title":"Commands and scripts have no effect","description":"","frontmatter":{"order":2,"adapter":"wled","editLink":"https://github.com/DrozmotiX/ioBroker.wled/edit/main/docs/en/04.fehlerbehebung/02.befehle-wirken-nicht.md"},"headers":[],"relativePath":"adapter/wled/fehlerbehebung/befehle-wirken-nicht.md","filePath":"adapter/wled/fehlerbehebung/befehle-wirken-nicht.md","lastUpdated":null}'),r={name:"adapter/wled/fehlerbehebung/befehle-wirken-nicht.md"};function i(d,e,c,h,l,m){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="commands-and-scripts-have-no-effect" tabindex="-1">Commands and scripts have no effect <a class="header-anchor" href="#commands-and-scripts-have-no-effect" aria-label="Permalink to &quot;Commands and scripts have no effect&quot;">​</a></h1><p><a id="off-state-not-updated"></a></p><h2 id="why-isn-t-the-on-off-state-updated" tabindex="-1">Why isn&#39;t the on/off state updated? <a class="header-anchor" href="#why-isn-t-the-on-off-state-updated" aria-label="Permalink to &quot;Why isn&#39;t the on/off state updated?&quot;">​</a></h2><p><em>This section is still being written.</em></p><p><a id="script-not-ps-wled-ignores"></a></p><h2 id="why-doesn-t-my-script-set-ps-or-on-or-why-does-wled-ignore-the-commands" tabindex="-1">Why doesn&#39;t my script set ps or on, or why does WLED ignore the commands? <a class="header-anchor" href="#why-doesn-t-my-script-set-ps-or-on-or-why-does-wled-ignore-the-commands" aria-label="Permalink to &quot;Why doesn&#39;t my script set ps or on, or why does WLED ignore the commands?&quot;">​</a></h2><p><strong>In short:</strong> It is usually one of five causes: the value was written as an acknowledgement (<code>ack=true</code>) instead of a control command, the device was offline for the adapter at that moment, the same preset was already active, the data type is wrong, or too many commands came too quickly one after another. The checklist below takes you through them in order.</p><p>This is how a command reaches the device: the adapter only reacts to writes with <code>ack=false</code>. It turns them into a JSON command, for example <code>{&quot;ps&quot;:3}</code> or <code>{&quot;on&quot;:true}</code>, and sends it right away: over the WebSocket connection if it is up, otherwise via HTTP to <code>http://192.168.x.y/json</code>. There is no queue and no retry.</p><p><img src="'+n+'" alt="How a command travels: only values with ack=false are sent, only to a connected device, via WebSocket or HTTP. Whatever doesn&#39;t arrive is lost."></p><h3 id="checklist" tabindex="-1">Checklist <a class="header-anchor" href="#checklist" aria-label="Permalink to &quot;Checklist&quot;">​</a></h3><ol><li><strong>Control, don&#39;t update.</strong> In Blockly, the block must be &quot;control&quot;, not &quot;update&quot;. In JavaScript, write <code>setState(id, value)</code> without <code>true</code> as the third argument. A value with <code>ack=true</code> counts as feedback from the device and is not sent.</li></ol><ol start="2"><li><strong>Test by hand.</strong> Write the same value to the state in the Admin object tree. If WLED reacts, the error is in the script, for example nested triggers or a wrong object ID. The device IDs are their MAC addresses; they don&#39;t change when you rename the device.</li></ol><ol start="3"><li><strong>Is the device online?</strong> Look at <code>wled.0.&lt;MAC&gt;._info._online</code>. Commands to a device that can&#39;t be reached are lost. The adapter doesn&#39;t buffer anything and doesn&#39;t retry. <ul><li><strong>Up to v0.9.2:</strong> The log shows an error &quot;Sending command to WLED device … failed with error …&quot;. If the adapter doesn&#39;t know the device at all at that moment, a TypeError appears there instead, which is also reported to Sentry.</li><li><strong>From v0.9.3:</strong> The adapter discards the command with the warning <code>Device &lt;MAC&gt; (192.168.x.y) is offline, command for … discarded</code> (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/904" target="_blank" rel="noreferrer">#904</a>).</li></ul></li></ol><ol start="4"><li><strong>Too soon after switching on?</strong> If WLED has only just been powered, for example via a smart plug, it takes a few seconds before it can be reached over Wi-Fi. Commands sent before that are lost. <ul><li><strong>From v0.9.3</strong> there is one more point: the adapter only sends to devices it knows to be connected (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/904" target="_blank" rel="noreferrer">#904</a>). It only notices that a device is back at the next check. By default this runs every 30 seconds (&quot;Intervall in seconds&quot;). If the device was off for longer, it checks less often: the intervals double up to a maximum of 10 minutes, and after 5 failed attempts (&quot;Max retry attempts&quot;) only once an hour. Until then it discards commands.</li><li>So let your script wait until <code>wled.0.&lt;MAC&gt;._info._online</code> becomes <code>true</code>, and only then send the command.</li></ul></li></ol><ol start="5"><li><strong>Same preset already active?</strong> If <code>ps</code> already shows the number you write, WLED doesn&#39;t load the preset again. This also happens if you switched the light off via <code>on</code> in between. In that case, send <code>{&quot;on&quot;:true,&quot;ps&quot;:3}</code> to <code>wled.0.&lt;MAC&gt;.action</code>.</li></ol><ol start="6"><li><strong>Is the data type right?</strong> <code>on</code> expects <code>true</code> or <code>false</code>, <code>ps</code> a number. If you write <code>on</code> as text, WLED does something other than you expect: a text starting with <code>t</code> (so <code>&quot;true&quot;</code> too) toggles the light, and <code>&quot;false&quot;</code> as text does nothing at all. ioBroker also logs a wrong data type as a warning.</li></ol><ol start="7"><li><strong>Too many commands in a row?</strong> Every changed state is a separate command. If your script writes <code>on</code>, <code>bri</code>, color and <code>ps</code> right after each other, WLED can lose commands or answer with a timeout. Combine values that belong together in one JSON command via <code>action</code>, for example <code>{&quot;on&quot;:true,&quot;bri&quot;:128,&quot;ps&quot;:3}</code>, or store them in a preset and only set <code>ps</code>. If they have to be single commands, leave a short pause between them.</li></ol><ol start="8"><li><strong>Feedback over WebSocket.</strong> If the connection runs over WebSocket, the adapter <strong>up to v0.9.2</strong> doesn&#39;t set <code>ack=true</code> itself and doesn&#39;t report a sending error either. The <code>ack</code> only comes when WLED reports its new state. If a value stays at <code>ack=false</code>, the command probably didn&#39;t arrive. <strong>From v0.9.3:</strong> The adapter sets <code>ack=true</code> as soon as the command has been sent, and writes a warning &quot;Sending command for … failed&quot; to the log if sending fails (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/904" target="_blank" rel="noreferrer">#904</a>).</li></ol><ol start="9"><li><strong>Segment commands.</strong> If you set a value in a segment, such as <code>wled.0.&lt;MAC&gt;.seg.0.fx</code>, the command only goes to that segment. Check that you picked the right segment and that it is switched on.</li></ol><ol start="10"><li><strong>Look at the debug log.</strong> Set the instance to log level &quot;debug&quot;. For every command, &quot;Sending state change by websocket …&quot; or &quot;Sending state change by http-API …&quot; then appears with the JSON that was sent. If the line is missing, the command never reached the adapter.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>If your script reads <code>on</code>, keep in mind: <strong>up to v0.9.2</strong> the adapter sets <code>on</code> to <code>false</code> and <code>bri</code> to <code>0</code> when a device goes offline, and when the adapter starts. <strong>From v0.9.3:</strong> Both keep their last value; the real values come from the device when it reconnects (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/899" target="_blank" rel="noreferrer">#899</a>).</p></div><p><strong>See also:</strong> <a href="./../anleitungen/effekte-und-presets#switch-wled-presets-via-ps">Switch presets via the ps state</a> · <a href="./../anleitungen/befehle-an-wled#send-complete-json-command-wled">Send a complete JSON command</a> · <a href="#several-commands-quick-succession-lead">Several commands lead to ETIMEDOUT</a> · <a href="./../hintergrund/verbindung-und-aktualisierung#tell-whether-device-really-online">How can I tell whether a device is online</a> · <a href="./../referenz/instanz-einstellungen#often-adapter-retry-offline-device">Retries for offline devices</a> · <a href="./../referenz/log-meldungen#warnings-about-wrong-data-type">Warnings about a wrong data type</a></p><p><a id="several-commands-quick-succession-lead"></a></p><h2 id="why-do-several-commands-in-quick-succession-lead-to-etimedout" tabindex="-1">Why do several commands in quick succession lead to ETIMEDOUT? <a class="header-anchor" href="#why-do-several-commands-in-quick-succession-lead-to-etimedout" aria-label="Permalink to &quot;Why do several commands in quick succession lead to ETIMEDOUT?&quot;">​</a></h2><p><em>This section is still being written.</em></p><p><a id="ps-jump-1-not-show"></a></p><h2 id="why-does-ps-jump-to-1-or-not-show-the-selected-preset" tabindex="-1">Why does ps jump to -1 or not show the selected preset? <a class="header-anchor" href="#why-does-ps-jump-to-1-or-not-show-the-selected-preset" aria-label="Permalink to &quot;Why does ps jump to -1 or not show the selected preset?&quot;">​</a></h2><p><em>This section is still being written.</em></p><p><a id="some-leds-stay-after-switching"></a></p><h2 id="why-do-some-leds-stay-on-after-switching-off" tabindex="-1">Why do some LEDs stay on after switching off? <a class="header-anchor" href="#why-do-some-leds-stay-on-after-switching-off" aria-label="Permalink to &quot;Why do some LEDs stay on after switching off?&quot;">​</a></h2><p><em>This section is still being written.</em></p><p><a id="cct-state-have-no-effect"></a></p><h2 id="why-does-the-cct-state-have-no-effect" tabindex="-1">Why does the cct state have no effect? <a class="header-anchor" href="#why-does-the-cct-state-have-no-effect" aria-label="Permalink to &quot;Why does the cct state have no effect?&quot;">​</a></h2><p><em>This section is still being written.</em></p>',34)])])}const f=t(r,[["render",i]]);export{p as __pageData,f as default};
